#include "mesh.h"#include "256.h"#include "FileStuff.h"#include "BMP.h"OSErr getElevation ( FSSpec theMeshFSSpec );OSErr getElevation ( FSSpec theMeshFSSpec ){//----------------------------------vars-------------------------------------------------- 	short		theMeshFileRef;	OSErr		theError;	unsigned char *theMap;	int i, j, k, x, y;	float max, min;	long meshSize, meshWidth, meshHeight;	long PictureSize, PictureWidth, PictureHeight;	Myth256Palette thePalette;	meshHeader theMeshHeader;	gridData *theGrid;//----------------------------------------------------------------------------------------		theError = FSpOpenDF ( &theMeshFSSpec, fsRdPerm, &theMeshFileRef );	if ( theError != noErr )		return theError;	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	PictureWidth = meshWidth * 16;	PictureHeight = meshHeight * 16;	PictureSize = PictureWidth * PictureHeight;	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	if ( theGrid == nil ){		FSClose ( theMeshFileRef );		return -1;	}	theMap = (unsigned char *) NewPtr (PictureSize);	if ( theMap == nil ){		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return -1;	}	FileSeek ( theMeshFileRef, 1088L );	FileRead ( theGrid, theMeshHeader.meshLength, theMeshFileRef );	FSClose ( theMeshFileRef );	// make the palette	for (i = 0; i < 256; i++){		thePalette.color[i].blue = i;		thePalette.color[i].green = i;		thePalette.color[i].red = i;	}	// find lowest and highest elevations on the map for scaling and zeroing	max = -10000;	min = 10000;	for ( i = 0; i < meshSize; i++ ){		if (theGrid[i].height > max)			max = theGrid[i].height;		if (theGrid[i].height < min)			min = theGrid[i].height;	}	max -= min;	if ( max == 0 )		max = 1;	// get the grid Z data into an array	for ( y = 0, i = 0; y < PictureSize - PictureWidth * 15; y += PictureWidth * 16 ){		for ( x = PictureWidth - 16; x >= 0; x -= 16, i++ ){			for ( k = 0; k < 16; k++ )				for ( j = 0; j < 16; j++ )					theMap[x + y + j + k * PictureWidth] = (char) ((theGrid[i].height - min) / (max / 255.0));			// raise everything up so the low is zero and scale		}	}	theError = writeBMP( "\p:Graphics.out:elevation.bmp", PictureWidth, PictureHeight, &thePalette, (char *) theMap );	DisposePtr ( (Ptr) theMap );	DisposePtr ( (Ptr) theGrid );	return theError;}